  "9/fizik": {"f":"fiz-9","u":[{"id":"u1","name":{"tr":"1. Ünite: Fizik Bilimi ve Kariyer Keşfi","en":"Unit 1: Physics and Career Exploration"},"outcomes":[{"id":"k1","code":"FİZ.9.1.1","title":{"tr":"Fizik biliminin diğer disiplinlerle ilişkisini belirleyerek fizik bilimini tanımlar.","en":"Defines physics by identifying its relationship with other disciplines."},"c":1},{"id":"k2","code":"FİZ.9.1.2","title":{"tr":"Fizik biliminin alt dallarını belirler ve sınıflandırır.","en":"Identifies and classifies the branches of physics."},"c":1},{"id":"k3","code":"FİZ.9.1.3","title":{"tr":"Fizik bilimine katkıda bulunan bilim insanlarının çalışmalarını ve deneyimlerini değerlendirir.","en":"Evaluates the work and experiences of scientists who contributed to physics."},"c":1},{"id":"k4","code":"FİZ.9.1.4","title":{"tr":"Bilim ve teknoloji kurumlarında fizikle ilişkili kariyer olanaklarını sorgular.","en":"Questions physics-related career opportunities in science and technology institutions."},"c":1}]},{"id":"u2","name":{"tr":"2. Ünite: Kuvvet ve Hareket","en":"Unit 2: Force and Motion"},"outcomes":[{"id":"k1","code":"FİZ.9.2.1","title":{"tr":"Temel ve türetilmiş nicelikleri sınıflandırır.","en":"Classifies fundamental and derived quantities."},"c":1},{"id":"k2","code":"FİZ.9.2.2","title":{"tr":"Skaler ve vektörel nicelikleri karşılaştırır.","en":"Compares scalar and vector quantities."},"c":1},{"id":"k3","code":"FİZ.9.2.3","title":{"tr":"Farklı doğrultulardaki vektörlerin yön ve büyüklüklerine yönelik çıkarım yapar.","en":"Makes inferences about the direction and magnitude of vectors in different directions."},"c":1},{"id":"k4","code":"FİZ.9.2.4","title":{"tr":"Vektörleri toplar ve bileşenlerine ayırır.","en":"Adds vectors and resolves them into components."},"c":1},{"id":"k5","code":"FİZ.9.2.5","title":{"tr":"Doğadaki temel kuvvetleri karşılaştırır.","en":"Compares the fundamental forces of nature."},"c":1},{"id":"k6","code":"FİZ.9.2.6","title":{"tr":"Hareketin temel kavramlarını tanımlar, bunlarla ilgili akıl yürütür.","en":"Defines the basic concepts of motion and reasons about them."},"c":1},{"id":"k7","code":"FİZ.9.2.7","title":{"tr":"Hareketleri türlerine göre sınıflandırır.","en":"Classifies motions by type."},"c":1}]},{"id":"u3","name":{"tr":"3. Ünite: Akışkanlar","en":"Unit 3: Fluids"},"outcomes":[{"id":"k1","code":"FİZ.9.3.1","title":{"tr":"Basınçla ilgili çıkarım yapar; basınca etki eden etmenleri belirler.","en":"Makes inferences about pressure and identifies the factors affecting it."},"c":1},{"id":"k2","code":"FİZ.9.3.2","title":{"tr":"Durgun sıvılarda basınçla ilgili çıkarım yapar.","en":"Makes inferences about pressure in static liquids."},"c":1},{"id":"k3","code":"FİZ.9.3.3","title":{"tr":"Günlük hayatta sıvı basıncının kullanımına ilişkin çıkarım yapar.","en":"Makes inferences about the use of liquid pressure in daily life."},"c":1},{"id":"k4","code":"FİZ.9.3.4","title":{"tr":"Açık hava basıncıyla ilgili çıkarım yapar.","en":"Makes inferences about atmospheric pressure."},"c":1},{"id":"k5","code":"FİZ.9.3.5","title":{"tr":"Deneyle kaldırma kuvvetinin bağlı olduğu değişkenleri analiz eder.","en":"Analyzes, through experiments, the variables the buoyant force depends on."},"c":1},{"id":"k6","code":"FİZ.9.3.6","title":{"tr":"Kaldırma kuvveti ile basıncı oluşturan kuvvet arasındaki ilişkiyi değerlendirir.","en":"Evaluates the relationship between the buoyant force and the force producing pressure."},"c":1},{"id":"k7","code":"FİZ.9.3.7","title":{"tr":"Akışkanın sürati ile basıncı arasındaki ilişkiyi günlük hayat örnekleriyle genelleştirir.","en":"Generalizes the relationship between a fluid's speed and pressure with everyday examples."},"c":1}]},{"id":"u4","name":{"tr":"4. Ünite: Enerji","en":"Unit 4: Energy"},"outcomes":[{"id":"k1","code":"FİZ.9.4.1","title":{"tr":"İç enerji, ısı ve sıcaklık arasındaki ilişkiyi kavrar.","en":"Understands the relationship between internal energy, heat and temperature."},"c":1},{"id":"k2","code":"FİZ.9.4.1","title":{"tr":"Kullanım amaçlarına göre termometre çeşitlerine örnek verir.","en":"Gives examples of thermometer types according to their purpose."},"c":1},{"id":"k3","code":"FİZ.9.4.2","title":{"tr":"Isı, öz ısı, ısı sığası ve sıcaklık farkı arasındaki matematiksel modele ulaşır.","en":"Arrives at the mathematical model relating heat, specific heat, heat capacity and temperature change."},"c":1},{"id":"k4","code":"FİZ.9.4.3","title":{"tr":"Saf maddelerin hâl değişimini etkileyen nitelikler ve gereken ısının bağlı olduğu değişkenler hakkında çıkarım yapar.","en":"Makes inferences about the factors affecting phase changes of pure substances and the variables the required heat depends on."},"c":1},{"id":"k5","code":"FİZ.9.4.4","title":{"tr":"Isıl denge durumuyla ilgili araştırma ve bilimsel gözlem yapar.","en":"Conducts research and scientific observation on thermal equilibrium."},"c":1},{"id":"k6","code":"FİZ.9.4.5","title":{"tr":"Isı aktarım yollarını sınıflandırır.","en":"Classifies the ways heat is transferred."},"c":1},{"id":"k7","code":"FİZ.9.4.6","title":{"tr":"Katılarda ısı iletim hızını etkileyen etmenlerle ilgili çıkarım yapar.","en":"Makes inferences about the factors affecting the rate of heat conduction in solids."},"c":1}]},{"id":"u5","name":{"tr":"5. Ünite (Ek): Madde ve Özellikleri","en":"Unit 5 (Extra): Matter and Its Properties"},"outcomes":[{"id":"k1","code":"FİZ.9.E1","title":{"tr":"Kütle, hacim ve özkütle; karışımların özkütlesi","en":"Mass, volume and density; density of mixtures"},"c":1},{"id":"k2","code":"FİZ.9.E2","title":{"tr":"Adezyon, kohezyon, yüzey gerilimi ve kılcallık","en":"Adhesion, cohesion, surface tension and capillarity"},"c":1}]}]},
